look.customCSS:
/* ───── 吐司 · 第一批 ───── */
[data-wk="chat"]{background:radial-gradient(circle at 20% 30%,rgba(233,182,110,.08),transparent 40%),#FAF5EC !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：奶油底，底下一条细线（不做框） */
[data-wk="chathead"]{background:#FAF5EC !important;border-bottom:none !important;box-shadow:0 1px 0 #EFE4D2 !important;gap:6px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#5A3E26 !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.08em !important}
[data-wk="headdim"]{color:#B5A48E !important;white-space:nowrap !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#5A3E26 !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#5A3E26 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：一个荷包蛋，头像就是蛋黄（描一圈蛋黄色） */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:50% !important;box-shadow:0 0 0 2.5px #FFC93C !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important;border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-34% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:-1 !important;pointer-events:none !important;filter:drop-shadow(0 2px 3px rgba(140,100,60,.15)) !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before{content:none !important}
[data-wk="msg"] [data-wk="row"]{gap:14px !important}

/* 气泡：一片吐司——一圈烤黄的面包边，顶上一个比身子略宽、中间鼓起的面包顶 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border:3px solid #B87A3E !important;border-top:none !important;border-radius:0 0 12px 12px !important;padding:6px 18px 10px !important;margin-top:22px !important;color:#5A3E26 !important;letter-spacing:.06em !important;box-shadow:0 3px 6px rgba(140,100,60,.12) !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;left:-8px !important;right:-8px !important;top:-22px !important;height:24px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;transform:none !important;bottom:auto !important;width:auto !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFFCF5 !important}
/* 我的：烤过的金黄吐司，右边抹一块黄油 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#E9B66E,#DFA45A) !important;padding-right:38px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:10px !important;top:50% !important;width:20px !important;height:18px !important;margin-top:-10px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:rotate(-8deg) !important;left:auto !important;bottom:auto !important}

/* 时间：一行淡棕小字 */
[data-wk="time"] > span{background:transparent !important;border:none !important;box-shadow:none !important;color:#B5A48E !important;letter-spacing:.15em !important;font-size:11.5px !important}
/* 已读＝后面一颗焦糖色小点；已送达＝浅灰小点 */
[data-wk="meta"]{color:#B5A48E !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::after{content:"" !important;width:8px !important;height:8px !important;flex:none !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PGNpcmNsZSBjeD0nNScgY3k9JzUnIHI9JzMuMicgZmlsbD0nI0Q5Q0NCOCcvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PGNpcmNsZSBjeD0nNScgY3k9JzUnIHI9JzMuMicgZmlsbD0nI0I4N0EzRScvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFCF5 !important;border:3px solid #B87A3E !important;border-radius:12px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#B87A3E !important}
[data-wk="name"]{color:#B5A48E !important}

/* 动描：没有框，棕色斜体，左边一道虚线（像撒的面包屑） */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{background:transparent !important;border:none !important;border-left:2px dotted #B87A3E !important;border-radius:0 !important;box-shadow:none !important;color:#8E7258 !important;font-style:italic !important;font-size:13px !important;line-height:1.8 !important;padding:2px 0 2px 14px !important}
/* 系统提示：一行小字 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#B5A48E !important;font-size:11px !important;font-style:normal !important;letter-spacing:.08em !important}

/* 底栏：白底一条，输入框浅灰胶囊；加号、发送是细圈，最右「让他回复」是焦糖色圆钮 */
[data-wk="composer"]{background:#fff !important;border-top:none !important;box-shadow:0 -1px 0 #EFE4D2,0 -4px 12px rgba(140,100,60,.05) !important;align-items:center !important;gap:10px !important}
[data-wk="chatinput"]{background:#F5F1EA !important;border:none !important;border-radius:12px !important;color:#5A3E26 !important}
[data-wk="chatinput"]::placeholder{color:#BFB3A2 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:34px !important;min-width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:44px !important;min-width:44px !important;height:44px !important;border-radius:50% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:#fff !important;border-top:1px solid #EFE4D2 !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}
/* ───── 吐司 · 第二批：卡片 ───── */
[data-wk="voice"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:#FFFCF5 !important;border:2.5px solid #B87A3E !important;border-radius:14px !important;box-shadow:0 3px 0 #E6D3B8 !important;color:#5A3E26 !important}
[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#5A3E26 !important;border-color:rgba(184,122,62,.3) !important}

/* 转账＝一罐草莓果酱：金额写在罐子上；收下罐子打开插一把勺，退回罐子空了 */
[data-wk="transfercard"]{position:relative !important;overflow:visible !important;background:#FFFCF5 !important;border:2.5px solid #B87A3E !important;border-radius:14px !important;box-shadow:0 3px 0 #E6D3B8 !important;color:#5A3E26 !important;padding-left:64px !important}
[data-wk="transfercard"]::before{content:"" !important;position:absolute !important;left:10px !important;top:50% !important;width:44px !important;height:54px !important;margin-top:-30px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"] *{color:#5A3E26 !important;border-color:rgba(184,122,62,.3) !important}
[data-wk="transferlabel"]{color:#B5A48E !important;letter-spacing:.2em !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#C2453E !important;font-weight:700 !important}
[data-wk="transferrule"]{border:none !important;height:8px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCA4Jz48ZyBmaWxsPScjQjg3QTNFJz48ZWxsaXBzZSBjeD0nMycgY3k9JzUnIHJ4PScxLjgnIHJ5PScxLjQnLz48ZWxsaXBzZSBjeD0nOCcgY3k9JzMnIHJ4PScxLjQnIHJ5PScxLjMnLz48ZWxsaXBzZSBjeD0nMTInIGN5PSc1LjUnIHJ4PScxLjInIHJ5PScxJy8+PC9nPjwvc3ZnPg==") center/14px 8px no-repeat,linear-gradient(90deg,transparent,#E6D3B8 20%,#E6D3B8 calc(50% - 10px),transparent calc(50% - 10px),transparent calc(50% + 10px),#E6D3B8 calc(50% + 10px),#E6D3B8 80%,transparent) center/100% 1.5px no-repeat !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:#F7EEDF !important}
[data-wk="transferbtn"]{border-radius:999px !important}
[data-wk="transferbtn"][data-part="take"]{background:#B87A3E !important;color:#fff !important;border:none !important}
[data-wk="transferbtn"][data-part="back"]{background:#fff !important;color:#B87A3E !important;border:1.5px solid #B87A3E !important}
[data-wk="transferseal"]{background:transparent !important;border:1.5px solid #B87A3E !important;color:#B87A3E !important;border-radius:50% !important;box-shadow:none !important}
[data-wk="transfercard"][data-status="accepted"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="returned"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.8 !important}

/* 红包＝一台烤面包机，两片吐司探出头；领完了吐司被拿走、只剩两缕热气 */
[data-wk="rpcard"]{position:relative !important;overflow:visible !important;width:220px !important;min-height:84px !important;padding:16px 16px 16px 88px !important;background:#FFFCF5 !important;border:2.5px solid #B87A3E !important;border-radius:14px !important;box-shadow:0 3px 0 #E6D3B8 !important;color:#5A3E26 !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:10px !important;top:50% !important;width:68px !important;height:58px !important;margin-top:-30px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="rpcard"]::after{content:"刚烤好" !important;position:absolute !important;right:12px !important;bottom:6px !important;font-size:10px !important;letter-spacing:.2em !important;color:#B5A48E !important}
[data-wk="rpcard"] *{color:#5A3E26 !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"] > div:not([data-wk]){padding:0 !important;background:transparent !important}
[data-wk="rpmsg"]{-webkit-line-clamp:2 !important;color:#8E5A2A !important}
[data-wk="rpcard"][data-status="done"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="rpcard"][data-status="done"]::after{content:"被拿走啦" !important}
[data-wk="rpenvelope"][data-stage="closed"],[data-wk="rpenvelope"][data-stage="open"]{background:linear-gradient(180deg,#E9B66E,#DFA45A) !important;border:4px solid #B87A3E !important;border-radius:60px 60px 22px 22px / 40px 40px 22px 22px !important;box-shadow:0 10px 30px rgba(140,100,60,.35) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:#FFFCF5 !important;border-color:#B87A3E !important;box-shadow:none !important}
[data-wk="rpenvelope"] [data-wk="rparc"]::after{content:none !important}
[data-wk="rpenvelope"] *{color:#5A3E26 !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 3px 4px rgba(140,100,60,.3)) !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
[data-wk="rpavatar"]{border-radius:50% !important;box-shadow:0 0 0 3px #FFC93C !important}
[data-wk="rpamount"]{color:#8E5A2A !important;background:none !important}
[data-wk="rpclose"]{background:#fff !important;border:2px solid #B87A3E !important;color:#B87A3E !important}

/* 照片＝嵌在一片吐司里：面包边当相框 */
[data-wk="photocard"]{position:relative !important;overflow:visible !important;background:#FFFCF5 !important;border:5px solid #DFA45A !important;border-top:none !important;border-radius:0 0 16px 16px !important;padding:8px 8px 22px !important;margin-top:24px !important;box-shadow:0 3px 6px rgba(140,100,60,.15) !important}
[data-wk="photocard"]::before{content:"" !important;position:absolute !important;left:-10px !important;right:-10px !important;top:-24px !important;height:26px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important}
[data-wk="photoface"]{background:#F4E3CF !important;border:none !important;border-radius:6px !important}
[data-wk="photoface"] *,[data-wk="phototext"]{color:#5A3E26 !important}
[data-wk="photocap"],[data-wk="photohint"]{color:#B5A48E !important}

/* 语音：前面一杯冒热气的牛奶 */
[data-wk="voice"] > *{background:transparent !important;box-shadow:none !important;border:none !important;color:#5A3E26 !important}
[data-wk="voice"][data-me]{padding:0 14px 0 38px !important;position:relative !important;border-radius:999px !important}
[data-wk="voice"]::before{content:"" !important;position:absolute !important;left:11px !important;top:50% !important;width:20px !important;height:20px !important;margin-top:-11px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important}
[data-wk="voice"][data-me="1"]{background:linear-gradient(180deg,#E9B66E,#DFA45A) !important}
[data-wk="voicewave"] span{background:#B87A3E !important}

[data-wk="wxcardsky"]{background:linear-gradient(170deg,#FFE7B8,#F6C98A) !important}
[data-wk="wxcardsky"] *{color:#5A3E26 !important}
[data-wk="wxcardsky"] svg{stroke:#B87A3E !important}
[data-wk="wxcardsay"]{background:#FFFCF5 !important;color:#5A3E26 !important;border-top:1.5px dashed #E6D3B8 !important}
/* 位置：一颗荷包蛋当图钉 */
[data-wk="geopin"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:none !important;border:none !important;width:28px !important;height:28px !important;border-radius:0 !important}
[data-wk="geopin"] *{opacity:0 !important}
[data-wk="geopinstem"]{background:#B87A3E !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 3px #FFC93C !important}

/* 拍一拍、通话结束：一行小字，两头撒面包屑 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCA4Jz48ZyBmaWxsPScjQjg3QTNFJz48ZWxsaXBzZSBjeD0nMycgY3k9JzUnIHJ4PScxLjgnIHJ5PScxLjQnLz48ZWxsaXBzZSBjeD0nOCcgY3k9JzMnIHJ4PScxLjQnIHJ5PScxLjMnLz48ZWxsaXBzZSBjeD0nMTInIGN5PSc1LjUnIHJ4PScxLjInIHJ5PScxJy8+PC9nPjwvc3ZnPg==") left center/14px 8px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCA4Jz48ZyBmaWxsPScjQjg3QTNFJz48ZWxsaXBzZSBjeD0nMycgY3k9JzUnIHJ4PScxLjgnIHJ5PScxLjQnLz48ZWxsaXBzZSBjeD0nOCcgY3k9JzMnIHJ4PScxLjQnIHJ5PScxLjMnLz48ZWxsaXBzZSBjeD0nMTInIGN5PSc1LjUnIHJ4PScxLjInIHJ5PScxJy8+PC9nPjwvc3ZnPg==") right center/14px 8px no-repeat !important;border:none !important;border-radius:0 !important;padding:2px 22px !important;color:#B5A48E !important;box-shadow:none !important}
[data-wk="note"][data-part="call"] svg{stroke:#B87A3E !important}
[data-wk="note"][data-part="callsum"]{color:#B5A48E !important}

/* 线下小结：一只牛皮纸面包袋，标题是袋口的贴纸 */
[data-part="offlog"]{background:repeating-linear-gradient(90deg,transparent 0 18px,rgba(140,100,60,.05) 18px 19px),#F1DDBF !important;border-color:#8E5A2A !important;padding-top:28px !important;position:relative !important}
[data-part="offlog"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:0 !important;height:10px !important;background:linear-gradient(135deg,transparent 50%,#F1DDBF 50%) 0 0/10px 10px repeat-x,#E3C79E !important;border-radius:12px 12px 0 0 !important}
[data-wk="offlogtitle"]{display:inline-block !important;margin:0 0 6px !important;padding:3px 14px !important;background:#fff !important;color:#B87A3E !important;border:1.5px solid #B87A3E !important;border-radius:999px !important;letter-spacing:.12em !important}
[data-wk="offlogtitle"] *{color:#B87A3E !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#8E5A2A !important}
[data-wk="offlogtranscript"]{border-top:1.5px dashed #B87A3E !important;color:#8E7258 !important}

/* 加号面板：一颗颗白吐司圆钮 */
[data-wk="chattoolicon"]{background:#FFFCF5 !important;border:2px solid #B87A3E !important;border-radius:50% !important;box-shadow:0 2px 0 #E6D3B8 !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#B87A3E !important;color:#B87A3E !important}
[data-wk="chattoollabel"]{color:#5A3E26 !important}

/* 引用 */
[data-wk="quotedraft"]{background:#FFF8EC !important;border:none !important;border-top:1.5px solid #EFE4D2 !important}
[data-wk="quotedraft"] *{color:#8E7258 !important;border-color:#B87A3E !important}
[data-wk="quoteicon"]{display:none !important}
[data-wk="quoteclear"]{color:#B87A3E !important}
[data-wk="quote"]{background:#FFF8EC !important;color:#8E7258 !important;border:1.5px solid #E6D3B8 !important;border-radius:10px !important;padding:3px 10px !important;opacity:1 !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid currentColor !important;padding-left:8px !important;opacity:.7 !important}
/* 顶栏：我和他的头像并排，各坐在一颗荷包蛋里当蛋黄；名字和小字不显示 */
[data-wk="chathead"] [data-wk="headname"]{display:none !important}
[data-wk="chathead"] button:has(> img[data-wk="avatar"]){position:relative !important;overflow:visible !important;isolation:isolate !important;display:flex !important;align-items:center !important;gap:24px !important;padding-left:8px !important}
